// App.js
import React, { useState } from 'react';
import './App.css'; // Import the Cyberpunk styles

function App() {
  const [searchTerm, setSearchTerm] = useState('');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleSearch = async () => {
    if (!searchTerm.trim()) {
        setError("INPUT REQUIRED: Please enter a trace vector.");
        setResults([]);
        return;
    }

    setLoading(true);
    setError(null);
    setResults([]);

    try {
      // Simulate asynchronous network/API latency (Cyberpunk delay)
      await new Promise(resolve => setTimeout(resolve, 1500)); 

      // Mock Data Generation based on search term
      const mockData = [
        { id: 'v1', title: `[CYBER-LOG] Data Stream Intercept: ${searchTerm} Alpha`, description: 'Encrypted feed recovered from Sector 7. High priority clearance required.' },
        { id: 'v2', title: `[NEO-NET] Glitch Report on Query: ${searchTerm}`, description: 'Analysis of unauthorized network traffic patterns detected near the corporate spire.' },
        { id: 'v3', title: `[TRACE] Target Location Beacon for: ${searchTerm}`, description: 'Geospatial coordinates pinging near the Old City Grid. Proceed with caution.' },
      ];

      setResults(mockData);

    } catch (err) {
      console.error("TRACE FAILED:", err);
      setError("SYSTEM FAILURE: Connection to the Data Hub was terminated.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>// VIDEO DATABASE ACCESS TERMINAL //</h1>
        <p>Awaiting Input Vector...</p>
      </header>

      <div className="search-container">
        <input
          type="text"
          className="search-input"
          placeholder="Enter keywords (e.g., 'Security Feed 3')"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          onKeyPress={(e) => {
            if (e.key === 'Enter' && !loading) {
              handleSearch();
            }
          }}
          disabled={loading}
        />
        <button className="search-button" onClick={handleSearch} disabled={loading}>
          {loading ? 'SCANNING...' : 'INITIATE TRACE'}
        </button>
      </div>

      {error && <div className="error-message">{error}</div>}

      {loading && !error && <div className="loading-message">LOADING... ACCESSING SECURE ARCHIVES...</div>}

      <div className="results-container">
        {!loading && results.length > 0 && results.map((video) => (
          <div key={video.id} className="video-card">
            <h3>{video.title}</h3>
            <p>{video.description}</p>
            <a href={`#video-${video.id}`} onClick={(e) => e.preventDefault()}>
              ACCESS FILE &gt;
            </a>
          </div>
        ))}
        {!loading && results.length === 0 && !error && searchTerm.trim() && (
             <div className="loading-message">NO MATCHES FOUND IN CURRENT SECTOR. TRACE TERMINATED.</div>
        )}
      </div>
    </div>
  );
}

export default App;
